const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Mount Fuji location
  const mountFuji = ee.Geometry.Point([138.73, 35.36]);
  const bufferRegion = mountFuji.buffer(5000); // 5km buffer

  // Function to calculate NDSI and filter clouds
  function calculateNDSI(image) {
    const ndsi = image.normalizedDifference(['B3', 'B6']).rename('NDSI');
    const cloudMask = image.select('BQA').lt(2720); // Mask clouds
    return ndsi.updateMask(cloudMask).copyProperties(image, ['system:time_start']);
  }

  // Collect NDSI for each December 2005-2015
  const decemberNDSI = [];
  let allValidMonths = 0;

  for (let year = 2005; year <= 2015; year++) {
    const startDate = `${year}-12-01`;
    const endDate = `${year}-12-31`;

    let col = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterDate(startDate, endDate)
      .filterBounds(bufferRegion);

    // Fallback to Landsat 8 if Landsat 5 not available
    if (col.size().getInfo() === 0) {
      col = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterDate(startDate, endDate)
        .filterBounds(bufferRegion);
    }

    const size = col.size().getInfo();
    if (size > 0) {
      const ndsiCol = col.map(calculateNDSI);
      const meanNDSI = ndsiCol.select('NDSI')
        .reduce(ee.Reducer.mean())
        .reduceRegion(
          ee.Reducer.first(),
          bufferRegion,
          300,
          null,
          null,
          false,
          1e9
        ).get('NDSI').getInfo();

      const pixelCount = ndsiCol.select('NDSI')
        .reduce(ee.Reducer.count())
        .reduceRegion(
          ee.Reducer.first(),
          bufferRegion,
          300,
          null,
          null,
          false,
          1e9
        ).get('count').getInfo();

      if (pixelCount > 0 && meanNDSI !== null && !isNaN(meanNDSI)) {
        decemberNDSI.push(meanNDSI);
        allValidMonths++;
        print(`Dec ${year}: NDSI=${meanNDSI.toFixed(3)}, Pixels=${pixelCount}`);
      } else {
        print(`Dec ${year}: No valid pixels`);
      }
    } else {
      print(`Dec ${year}: Images=0`);
    }
  }

  // Get December 2020 NDSI
  const col2020 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterDate('2020-12-01', '2020-12-31')
    .filterBounds(bufferRegion);

  const size2020 = col2020.size().getInfo();
  if (size2020 === 0) {
    print("Dec 2020: Images=0");
    print("<answer>C1</answer>");
    return;
  }

  const ndsiCol2020 = col2020.map(calculateNDSI);
  const meanNDSI2020 = ndsiCol2020.select('NDSI')
    .reduce(ee.Reducer.mean())
    .reduceRegion(
      ee.Reducer.first(),
      bufferRegion,
      300,
      null,
      null,
      false,
      1e9
    ).get('NDSI').getInfo();

  const pixelCount2020 = ndsiCol2020.select('NDSI')
    .reduce(ee.Reducer.count())
    .reduceRegion(
      ee.Reducer.first(),
      bufferRegion,
      300,
      null,
      null,
      false,
      1e9
    ).get('count').getInfo();

  if (pixelCount2020 === 0) {
    print("Dec 2020: No valid pixels");
    print("<answer>C2</answer>");
    return;
  }

  if (meanNDSI2020 === null || isNaN(meanNDSI2020) || meanNDSI2020 < -1 || meanNDSI2020 > 1) {
    print("Dec 2020: Invalid NDSI value");
    print("<answer>C3</answer>");
    return;
  }

  print(`Dec 2020: NDSI=${meanNDSI2020.toFixed(3)}, Pixels=${pixelCount2020}`);

  if (allValidMonths === 0) {
    print("No valid comparison data");
    print("<answer>C1</answer>");
    return;
  }

  // Check if 2020 is lower than ALL Decembers 2005-2015
  const isLowerThanAll = decemberNDSI.every(val => meanNDSI2020 < val);

  print(`Valid comparisons: ${allValidMonths}`);
  print(`Min(2005-2015)=${Math.min(...decemberNDSI).toFixed(3)}`);

  if (isLowerThanAll) {
    print("<answer>A</answer>");
  } else {
    print("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
